<?php
namespace App\Controller;
use App\Core\{Auth,Controller};use App\Repository\{ClassRepository,LecturerRepository,SemesterRepository};
class TeacherController extends Controller {public function __construct(private \PDO $pdo){}public function dashboard():void{Auth::requireRole('teacher');$sem=(int)($_GET['semester_id']??0);$repo=new LecturerRepository($this->pdo);$schedule=$repo->schedule(Auth::id(),$sem?:null);$classes=(new ClassRepository($this->pdo))->findLecturerClasses(Auth::id());$this->view('teacher/dashboard',['schedule'=>$schedule,'classes'=>$classes,'semesters'=>(new SemesterRepository($this->pdo))->findAll(),'semesterId'=>$sem]);}public function classDetail():void{Auth::requireRole('teacher');$id=(int)($_GET['id']??0);$class=(new ClassRepository($this->pdo))->findById($id);if(!$class||!array_key_exists('lecturer_id',$class)||(int)$class['lecturer_id']!==Auth::id()){http_response_code(403);exit('Bạn không có quyền xem lớp này.');}$this->view('teacher/class',['class'=>$class]);}public function grades():void{Auth::requireRole('teacher');$id=(int)($_GET['id']??0);$class=(new ClassRepository($this->pdo))->findById($id);if(!$class||(int)$class['lecturer_id']!==Auth::id()){http_response_code(403);exit('Không có quyền.');}$this->view('teacher/grades',['class'=>$class]);}}
